          "check_id": "CHK-W5B6-49-001",
          "property_id": "PROP-W5B6-49",
          "title": "Verify Trust Boundary Integrity: Are EIP-7702 SetCodeTransaction authorization signatures individually validated with proper ECDSA verification?",
          "severity": "Critical",
          "mindset": "Boundary Guard",
          "is_boundary_check": true,
          "reachability": {
            "classification": "external-reachable",
            "entry_points": [
              "P2P",
              "Transaction"
            ],
            "attacker_controlled": true,
            "validation_layers": [
              "ECDSA signature verification",
              "chain_id validation",
              "Nonce validation"
            ],
            "bug_bounty_scope": "in-scope",
            "notes": "EIP-7702 allows code delegation for EOAs. Weak authorization validation enables account takeover."
          },
          "test_procedure": "1. Identify all code paths that process EIP-7702 SetCodeTransaction authorizations in the execution engine.\n2. Verify that each authorization tuple undergoes individual ECDSA signature verification before processing.\n3. Attempt to submit a SetCodeTransaction with a forged or invalid signature and confirm it is rejected.\n4. Test signature malleability by submitting transactions with mathematically valid but non-canonical signatures.\n5. Verify that the recovered signer address matches the authorizing account address explicitly.\n6. Check that signature verification uses the correct message hash including chain_id, address, and nonce.\n7. Confirm that authorization lists with mixed valid/invalid signatures are fully rejected (no partial processing).",
          "bug_class": "Input Validation",
          "risk_category": "Elevation of Privilege",
          "notes": "Source: PROP-W5B6-49, Trust Boundary: tb-022, Threat: stride-eop-tb-022, Assumption: asm-025"
        },
        "code_scope": {
